      private void ReportHeader_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e){
xrPictureBox1.Image = AlphaWebReports.raporteUtil.MerrLogoNdermarrje(this.Extensions["ndermarrjeLogo"]);

        }

        private void shitjePivotGrid_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e)
        {
            shitjePivotGrid.BestFit();
        }

        private void shitjePivotGrid_CustomFieldSort(object sender, DevExpress.XtraReports.UI.PivotGrid.PivotGridCustomFieldSortEventArgs e)
        {


            if (e.Field.FieldName == "data")
            {

                DateTime orderValue1 =Convert.ToDateTime( e.GetListSourceColumnValue(e.ListSourceRowIndex1, "data"));
                DateTime orderValue2 =Convert.ToDateTime( e.GetListSourceColumnValue(e.ListSourceRowIndex2, "data"));
                e.Result = Comparer.Default.Compare(e.Value1, e.Value2);
                if (e.Result != 0)
                    e.Result = Comparer.Default.Compare(orderValue1, orderValue2);
                e.Handled = true;

            }

        }

        private void shitjePivotGrid_CustomFieldValueCells(object sender, DevExpress.XtraReports.UI.PivotGrid.PivotCustomFieldValueCellsEventArgs e)
        {
              if (shitjePivotGrid.RowCount == 1 && shitjePivotGrid.ColumnCount == 1)
                return;
            for (int i = 0; i < shitjePivotGrid.RowCount; i++)
            {
                    DevExpress.XtraReports.UI.PivotGrid.FieldValueCell cell0 = e.GetCell(false, 0);
                    DevExpress.XtraReports.UI.PivotGrid.FieldValueCell cell1 = e.GetCell(false, 1);
                    DevExpress.XtraReports.UI.PivotGrid.FieldValueCell cell2 = e.GetCell(false, 2);
                    DevExpress.XtraReports.UI.PivotGrid.FieldValueCell cell3 = e.GetCell(false, 3);
                    DevExpress.XtraReports.UI.PivotGrid.FieldValueCell cell4 = e.GetCell(false, 4);
                    DevExpress.XtraReports.UI.PivotGrid.FieldValueCell cell5 = e.GetCell(false, 5);
                    if (cell0 == null || cell1 == null || cell2 == null || cell3 == null || cell4 == null || cell5==null) continue;
                    if ((cell0.DisplayText == "") && (cell1.DisplayText == "") && (cell2.DisplayText == "") && (cell3.DisplayText == "")
                        && (cell4.DisplayText == "") && (cell5.DisplayText == ""))
                        e.Remove(cell0);


            }

        }
private void filtraTable_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
AlphaWebReports.raporteUtil.shtoFiltra(filtraTable, null, AlphaWebReports.raporteUtil.DeserializoParametrat(this.Extensions["filtrat"]));
}
